</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <iostream>
#include <algorithm>
#include <string>
#include <cstring>
#include <vector>
#include <queue>
#include <limits>
#include <utility>
#include <iomanip>
#include <cassert>
#include <cmath>
#include <map>
#include <stack>
#include <numeric>
#include <set>

#define endl '\n'
using namespace std;

typedef long long ll;

struct Fraction {
    ll a, b;
};

pair<ll, ll> geta(int x, int y, int b) {
    ll lower = (ll)b * x / y;
    ll upper = ((ll)b * x + (y-1)) / y;
    return {lower, upper};
}

int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

void solve(int x, int y, int n) {
    vector<Fraction> cands;
    for (int b = 1; b <= n; b++) {
        auto ap = geta(x, y, b);
        cands.push_back({ap.first, b});
        cands.push_back({ap.second, b});
    }

    auto comp = [&](Fraction fa, Fraction fb)-> bool {
        ll a1 = fa.a;
        ll b1 = fa.b;
        ll a2 = fb.a;
        ll b2 = fb.b;

        ll left = abs(x * b1 * b2 - a1 * b2 * y);
        ll right = abs(x * b1 * b2 - a2 * b1 * y);

        if (left < right) return true;
        else if (left > right) return false;

        if (b1 < b2) return true;
        else if (b1 > b2) return false;

        if (a1 < a2) return true;
        return false;
    };

    sort(cands.begin(), cands.end(), comp);

    //cout << (double)x / y << endl;
    //cout << comp({0, 1}, {2, 5}) << endl;
    //for (auto f : cands) {
    //    cout << f.a << "/" << f.b << " " << (double)f.a / f.b << endl;
    //}

    cout << cands.front().a << "/" << cands.front().b << endl;
}

int main(){
    std::ios_base::sync_with_stdio(false);
    cin.tie(0);
    int x, y, n;
    cin >> x >> y >> n;

    solve(x, y, n);
    return 0;
}
</original_code>
